var doc = app.activeDocument;
var a = doc.assets.addFromSelection();
a.assetName = 'icon-cart';
$.writeln(a.assetID + ' -> ' + a.getNormalizedName());

var cfg = new GridRepeatConfig();   // ExtendScript constructor unverified; the COM coclass is creatable
cfg.horizontalSpacing = 12;
cfg.verticalSpacing = 12;
var doc = app.activeDocument;
var grid = doc.gridRepeatItems.add(doc.selection[0], cfg);

var doc = app.activeDocument;
var item = doc.gridRepeatItems[0];
var cfg = item.gridConfig;
$.writeln(cfg.horizontalSpacing + ' x ' + cfg.verticalSpacing);
cfg.horizontalSpacing = 24;
item.setGridConfiguration(cfg, GridRepeatUpdate.GRIDALL);

var cfg = new RadialRepeatConfig();   // ExtendScript constructor unverified; the COM coclass is creatable
cfg.numberOfInstances = 12;
cfg.radius = 150;
cfg.reverseOverlap = false;
var doc = app.activeDocument;
var ring = doc.radialRepeatItems.add(doc.selection[0], cfg);

var doc = app.activeDocument;
var item = doc.radialRepeatItems[0];
var cfg = item.radialConfig;
cfg.numberOfInstances = 16;
item.setRadialConfiguration(cfg, RadialRepeatUpdate.NUMBEROFINSTANCES);

var cfg = new SymmetryRepeatConfig();   // ExtendScript constructor unverified; the COM coclass is creatable
cfg.axisRotationAngleInRadians = Math.PI / 2;
var doc = app.activeDocument;
var mirror = doc.symmetryRepeatItems.add(doc.selection[0], cfg);

var doc = app.activeDocument;
var item = doc.symmetryRepeatItems[0];
var cfg = item.symmetryConfig;
cfg.axisRotationAngleInRadians = Math.PI / 4;
item.setSymmetryConfiguration(cfg, SymmetryRepeatUpdate.AXISROTATION);

var abs = app.activeDocument.artboards;
abs.add([0, 0, 1080, -1350]);
abs.setActiveArtboardIndex(abs.length - 1);
$.writeln(abs.getActiveArtboardIndex() + ' of ' + abs.length);

var styles = app.activeDocument.graphicStyles;
$.writeln(styles.length + ' styles');
var neon = null;
try { neon = styles.getByName('Neon Glow'); } catch (e) {}

var doc = app.activeDocument;
var a = doc.assets.add(doc.pageItems[0]);
var again = doc.assets.getByID(a.assetID);
$.writeln(doc.assets.length);
doc.assets.remove(a.assetID);

var brushes = app.activeDocument.brushes;
$.writeln(brushes.length + ' brushes');
var ink = null;
try { ink = brushes.getByName('Charcoal - Feather'); } catch (e) {}

var tf = app.activeDocument.textFrames[0];
var chars = tf.characters;
$.writeln(chars.length + ' characters');
var first = chars[0];
chars.add(' / 2026');

var cs = app.activeDocument.characterStyles;
var price = null;
try { price = cs.getByName('Price'); }
catch (e) { price = cs.add('Price'); }
$.writeln(cs.length + ' character styles');

var doc = app.activeDocument;
var ring = doc.compoundPathItems.add();
ring.pathItems.ellipse(-100, 100, 300, 300);
ring.pathItems.ellipse(-175, 175, 150, 150, true);
$.writeln(doc.compoundPathItems.length);

var doc = app.activeDocument;
var sets = doc.dataSets;
var rec = sets.add();
$.writeln(sets.length + ' data sets');

var docs = app.documents;
var before = docs.length;
var doc = docs.add();
$.writeln(before + ' -> ' + docs.length);

var emb = app.activeDocument.embeddedItems;
$.writeln(emb.length + ' embedded items');
for (var i = 0; i < emb.length; i++) $.writeln(emb[i].typename);

var grads = app.activeDocument.gradients;
var g = grads.add();
var stops = g.gradientStops;
$.writeln(grads.length + ' gradients; new one has ' + stops.length + ' stops');

var g = app.activeDocument.gradients.add();
var stops = g.gradientStops;
var mid = stops.add();
$.writeln(stops.length + ' stops');

var graphs = app.activeDocument.graphItems;
$.writeln(graphs.length + ' graphs');
var g = null;
try { g = graphs.getByName('Q3 sales'); } catch (e) {}

var doc = app.activeDocument;
var cfg = new GridRepeatConfig();   // ExtendScript constructor unverified; the COM coclass is creatable
cfg.horizontalSpacing = 20;
cfg.verticalSpacing = 20;
var grid = doc.gridRepeatItems.add(doc.selection[0], cfg);
$.writeln(doc.gridRepeatItems.length);

var doc = app.activeDocument;
var logo = doc.groupItems.createFromFile(new File('C:/brand/logo.svg'));
var holder = doc.groupItems.add();
$.writeln(doc.groupItems.length + ' groups');

var tf = app.activeDocument.textFrames[0];
var ips = tf.insertionPoints;
var end = ips[ips.length - 1];
end.characters.add(' *');

var layers = app.activeDocument.layers;
var art = null;
try { art = layers.getByName('Art'); }
catch (e) { art = layers.add(); art.name = 'Art'; }
$.writeln(layers.length + ' layers');

var legacy = app.activeDocument.legacyTextItems;
if (legacy.length > 0) {
  var ok = legacy.convertToNative();
  $.writeln('converted: ' + ok);
}

var tf = app.activeDocument.textFrames[0];
var lines = tf.lines;
$.writeln(lines.length + ' lines');
var firstLine = lines[0];

var ls = app.activeDocument.listStyles;
var steps = null;
try { steps = ls.getByName('Steps'); }
catch (e) { steps = ls.add('Steps'); }
$.writeln(ls.length + ' list styles');

var meshes = app.activeDocument.meshItems;
$.writeln(meshes.length + ' gradient meshes');
for (var i = meshes.length - 1; i >= 0; i--) $.writeln(meshes[i].typename);

var items = app.activeDocument.layers[0].pageItems;
for (var i = items.length - 1; i >= 0; i--) {
  $.writeln(i + ': ' + items[i].typename);
}

var tf = app.activeDocument.textFrames[0];
var paras = tf.paragraphs;
paras.add('New feature line');
$.writeln(paras.length + ' paragraphs');

var ps = app.activeDocument.paragraphStyles;
var body = null;
try { body = ps.getByName('Body'); }
catch (e) { body = ps.add('Body'); }
$.writeln(ps.length + ' paragraph styles');

var p = app.activeDocument.pathItems;
var bg = p.rectangle(0, 0, 1080, 1080);
var btn = p.roundedRectangle(-880, 240, 600, 120, 60, 60);
var badge = p.star(860, -220, 140, 110, 24);
var dot = p.ellipse(-100, 100, 80, 80);

var path = app.activeDocument.pathItems.add();
var pts = path.pathPoints;
var a = pts.add();
a.anchor = [100, -100]; a.leftDirection = a.anchor; a.rightDirection = a.anchor;
var b = pts.add();
b.anchor = [300, -100]; b.leftDirection = b.anchor; b.rightDirection = b.anchor;

var pats = app.activeDocument.patterns;
$.writeln(pats.length + ' patterns');
var p = null;
try { p = pats.getByName('Pinstripe'); } catch (e) {}

var doc = app.activeDocument;
var img = doc.placedItems.add();
img.file = new File('C:/assets/product.png');
$.writeln(doc.placedItems.length + ' placed');

var plugs = app.activeDocument.pluginItems;
for (var i = 0; i < plugs.length; i++) {
  $.writeln(i + ': ' + plugs[i].typename);
}
